package com.example

import android.graphics.BitmapFactory
import android.util.Base64
import androidx.compose.foundation.Image
import androidx.compose.foundation.layout.size
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.graphics.asImageBitmap
import androidx.compose.ui.layout.ContentScale
import androidx.compose.ui.unit.Dp
import androidx.compose.ui.unit.dp

/**
 * Official Wisdom Tower mark (from brand PNG).
 * Embedded as base64 so the top bar logo works offline and never disappears.
 */
private const val BRAND_ICON_BASE64 =
    ""

@Composable
fun BrandMark(
    size: Dp = 34.dp,
    corner: Dp = 8.dp,
) {
    val bitmap = remember {
        val bytes = Base64.decode(BRAND_ICON_BASE64, Base64.DEFAULT)
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size)?.asImageBitmap()
    }
    if (bitmap != null) {
        Image(
            bitmap = bitmap,
            contentDescription = "Wisdom Tower",
            contentScale = ContentScale.Fit,
            modifier = Modifier
                .size(size)
                .clip(RoundedCornerShape(corner)),
        )
    }
}
